def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)

    # Frequent non-background colors are the colors of the rectangular objects.
    min_count = max(10, (h * w + 24) // 25)
    object_colors = {c for c, n in counts.items() if c != bg and n >= min_count}

    out = [[bg] * w for _ in range(h)]

    # Object rectangles contain their object color and may have noise-colored
    # cells, but have no background-colored cells.
    for color in object_colors:
        for r0 in range(h):
            for r1 in range(r0 + 1, h):
                for c0 in range(w):
                    for c1 in range(c0 + 1, w):
                        area = (r1 - r0 + 1) * (c1 - c0 + 1)
                        same = 0
                        valid = True
                        for r in range(r0, r1 + 1):
                            for c in range(c0, c1 + 1):
                                if grid[r][c] == bg:
                                    valid = False
                                    break
                                if grid[r][c] == color:
                                    same += 1
                            if not valid:
                                break
                        if valid and same >= 3 and same / area >= 0.65:
                            for r in range(r0, r1 + 1):
                                for c in range(c0, c1 + 1):
                                    out[r][c] = color
    return out
